import { Component, OnInit } from '@angular/core';
import { Location } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { BuscadorComponent } from '../../components/buscador/buscador.component';
import { MatIconModule } from '@angular/material/icon';
import { ResultadosBusquedaComponent } from 'src/app/components/resultados-busqueda/resultados-busqueda.component';
import { JumbotronComponent } from '../jumbotron/jumbotron.component';
import { ActivatedRoute } from '@angular/router';
import { NavbarComponent } from 'src/app/shared/navbar/navbar.component';
import { FuncionesComunes } from 'src/app/core/funciones-comunes/funciones-comunes.service';
import { IonicModule, ModalController, NavController } from '@ionic/angular';
import { TranslateModule } from '@ngx-translate/core';
import { Viaje } from 'src/app/models/travel/viaje.model';
import { AbrirIncidenciaModalComponent } from 'src/app/components/abrir-incidencia-modal/abrir-incidencia-modal.component';
import { MessageService } from 'primeng/api';

@Component({
  selector: 'app-busqueda-viajes',
  templateUrl: './busqueda-viajes.page.html',
  styleUrls: ['./busqueda-viajes.page.scss'],
  standalone: true,
  imports: [
    IonicModule,
    FormsModule,
    BuscadorComponent,
    MatIconModule,
    ResultadosBusquedaComponent,
    JumbotronComponent,
    NavbarComponent,
    TranslateModule,
  ],
})
export class BusquedaViajesPage implements OnInit {
  userLoggedIn: boolean = false;

  mostrarJumbotron = true;
  /** Objeto para guardar los parámetros que vienen en la URL */
  busquedaParams: any;

  irAtras: string = '../../../assets/sistema/atras.png';
  imgNuevoViaje: string = '../../../assets/sistema/agregar.png';

  filtroSeleccionado: string = 'horaSalida';
  isLoading: boolean = false;
  listado_viajes: Viaje[] = [];

  constructor(
    private route: ActivatedRoute,
    private funcionesComunes: FuncionesComunes,
    private location: Location,
    private navCtrl: NavController,
    private modalController: ModalController,
    public messageService: MessageService
  ) {}

  ngOnInit() {
    this.userLoggedIn = this.funcionesComunes.isUserLoggedIn();
    this.loadJumbotronSetting();
    /**
     * Aquí se obtienen los datos de los parámetros de la URL.
     */
    this.route.queryParams.subscribe((params) => {
      this.busquedaParams = params;
      console.log('Parámetros de búsqueda recibidos:', this.busquedaParams);
    });
  }

  /**
   * Función para cargar la configuración del jumbotron desde el localStorage
   */
  loadJumbotronSetting() {
    const jumbotronSetting = localStorage.getItem('mostrarJumbotron');
    this.mostrarJumbotron = jumbotronSetting === null ? true : jumbotronSetting === 'true';
  }

  /**
   * Función para ir a la página anterior
   */
  goBack() {
    this.location.back();
  }

  /**
   * Función para navegar a la página de nuevo viaje
   */
  goToNuevoViaje() {
    this.navCtrl.navigateRoot('/nuevo-viaje');
  }

  /**
   * Función para cambiar el filtro seleccionado
   */
  onFiltroChange(event: any, popover: any) {
    const valor = event.detail.value;
    this.filtroSeleccionado = valor;
    popover.dismiss();
  }

  /**
   * Función para actualizar los parámetros de búsqueda
   * cuando el componente hijo emite un evento con los nuevos parámetros
   * @param event --> Objeto con los nuevos parámetros de búsqueda
   */
  actualizarParametrosBusqueda(event: any) {
    this.busquedaParams = event;
  }

  /**
   * Función para comprobar si se han recibido parámetros de búsqueda en la URL
   * @returns --> true si hay parámetros, false si no los hay
   * Esta función se utiliza para mostrar u ocultar el botón de filtro dependiendo de si hay parámetros de búsqueda o no.
   */
  tieneParametros(): boolean {
    return Object.keys(this.busquedaParams).length > 0;
  }

  async abrirIncidenciaBusqueda() {
    const modal = await this.modalController.create({
      component: AbrirIncidenciaModalComponent,
      componentProps: {
        categoria: 'VIAJE',
        subcategoriaPredeterminada: 'OTRO',
        tituloContexto: 'Incidencia en búsqueda de viajes',
      },
      cssClass: 'modal-incidencia-custom',
    });

    await modal.present();
    const { role } = await modal.onWillDismiss();

    if (role === 'confirm') {
      this.messageService.add({
        severity: 'success',
        summary: 'Incidencia enviada',
        detail: 'Gracias por informarnos. Revisaremos el problema con el buscador a la brevedad.',
        life: 4000,
      });
    }
  }
}
